import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- elementwise addition custom CUDA operator ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* __a, const float* __b, float* __out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        __out[idx] = __a[idx] + __b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- 3D matrix multiplication custom CUDA operator ----------
matmul_kernel_source = """
__global__ void matmul_3d_kernel(const float* __A, const float* __B, float* __C, int N, int M, int K, int L) {
    // Each thread computes one output element C[n][m][l]
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * M * L) {
        int n = idx / (M * L);
        int rem = idx % (M * L);
        int m = rem / L;
        int l = rem % L;

        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            // A index: n*M*K + m*K + k
            // B index: k*L + l
            sum += __A[n * M * K + m * K + k] * __B[k * L + l];
        }
        __C[idx] = sum;
    }
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_3d_kernel(const float* __A, const float* __B, float* __C, int N, int M, int K, int L) {
    // same as above
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto out = torch::zeros_like(A);

    int N = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int L = B.size(1);

    const int block_size = 256;
    const int num_blocks = (N * M * L + block_size - 1) / block_size;

    matmul_3d_kernel<<<num_blocks, block_size>>>(A.data_ptr<float()>, B.data_ptr<float()>, out.data_ptr<float()>, N, M, K, L);

    return out;
}
"""

matmul = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Optimized model ----------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul_cuda = matmul

    def forward(self, A, B):
        return self.matmul_cuda(A, B)
